INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Satu Password Tidak Cukup Lagi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setiap tahun jutaan password bocor dari berbagai layanan. Peretas tidak menebak passwordmu satu per satu, mereka memakai daftar password bocor (credential stuffing) dan mencobanya ke ribuan situs sekaligus. Jika kamu memakai password yang sama di banyak tempat, satu kebocoran saja cukup untuk mengambil alih email, media sosial, bahkan akun bankmu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Apa Itu Two-Factor Authentication$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Two-Factor Authentication (2FA) atau autentikasi dua faktor menambahkan lapisan kedua saat login: selain sesuatu yang kamu tahu (password), kamu harus membuktikan sesuatu yang kamu miliki. Bentuknya bermacam-macam: kode SMS (OTP), aplikasi authenticator yang menghasilkan kode 6 digit berubah tiap 30 detik (TOTP), kunci keamanan fisik, hingga passkey modern. Dengan 2FA aktif, password yang bocor saja tidak cukup bagi peretas.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Ponsel dengan aplikasi authenticator (Google Authenticator, Microsoft Authenticator, atau Authy)$txt$, $txt$Akses ke email pemulihan akunmu$txt$, $txt$Kertas atau pengelola password untuk menyimpan kode cadangan (backup code)$txt$, $txt$Nomor HP aktif jika layanan memakai OTP SMS$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Aktifkan 2FA di Akun Pentingmu$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Buka pengaturan keamanan akun (biasanya di menu Keamanan atau Privasi), lalu pilih opsi Verifikasi 2 langkah atau 2FA.$txt$, $txt$Pilih metode aplikasi authenticator (lebih aman daripada SMS), lalu pindai kode QR yang muncul dengan aplikasimu.$txt$, $txt$Masukkan kode 6 digit dari aplikasi untuk memverifikasi, lalu simpan kode cadangan (backup code) di tempat aman.$txt$, $txt$Ulangi untuk akun terpenting: email utama, WhatsApp/Telegram, media sosial, dan mobile banking.$txt$, $txt$Hapus metode lama yang tidak dipakai dan pastikan nomor HP pemulihan masih aktif.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Jebakan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Risiko terbesar 2FA adalah kehilangan akses: jika HP hilang dan kamu tidak menyimpan kode cadangan, kamu bisa terkunci dari akun sendiri. Kode OTP via SMS juga rentan terhadap penipuan SIM swap, jadi authenticator lebih disarankan. Ingat, 2FA bukan anti-phishing sempurna: situs palsu tetap bisa menipumu mengetikkan kode, jadi selalu periksa alamat situs sebelum login.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$2FA sudah aktif di email utama, media sosial, dan akun keuangan.$txt$, $txt$Kode cadangan tersimpan di tempat aman (bukan di HP yang sama).$txt$, $txt$Uji dengan logout lalu login kembali: sistem meminta kode kedua.$txt$, $txt$Nomor HP dan email pemulihan sudah diperbarui dan bisa diakses.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Keringat Berlebih Mengganggu Aktivitas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Telapak tangan basah saat berjabat tangan, ketiak selalu lembap meski tidak panas, atau kaki bau karena sepatu basah keringat. Kondisi ini disebut hiperhidrosis, keringat berlebih yang tidak sebanding dengan kebutuhan tubuh mendinginkan diri. Selain tidak nyaman, ia bisa menurunkan rasa percaya diri dalam bekerja dan bergaul.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Mengapa Tubuh Berkeringat Berlebih$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Keringat dihasilkan kelenjar ekrin yang tersebar di seluruh kulit, paling padat di telapak tangan, kaki, dan ketiak. Pemicunya bisa panas, stres atau cemas, makanan pedas, kafein, dan alkohol. Hiperhidrosis primer biasanya muncul sejak remaja dan bersifat turunan, sedangkan yang muncul tiba-tiba di usia dewasa atau disertai gejala lain bisa menandakan kondisi medis tertentu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan dan Alat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Antiperspiran (bukan deodoran biasa), pilih yang mengandung aluminium klorida$txt$, $txt$Bedak tabur atau bedak khusus kaki untuk menyerap kelembapan$txt$, $txt$Pakaian berbahan katun atau kain penyerap keringat, hindari bahan sintetis ketat$txt$, $txt$Tisu basah dan kaus kaki cadangan untuk dibawa bepergian$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Mengatasi Keringat Berlebih$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Oleskan antiperspiran pada malam hari sebelum tidur ke area bermasalah (ketiak, telapak tangan), bukan setelah mandi pagi, agar bekerja maksimal.$txt$, $txt$Pilih pakaian longgar berbahan menyerap keringat dan ganti kaus kaki minimal sekali sehari.$txt$, $txt$Kelola stres dengan napas dalam atau relaksasi, karena kecemasan adalah pemicu utama keringat di telapak tangan.$txt$, $txt$Batasi pemicu: kurangi kopi, makanan pedas, dan alkohol terutama sebelum acara penting.$txt$, $txt$Untuk kaki, taburi bedak di dalam sepatu dan biarkan sepatu kering sempurna sebelum dipakai lagi.$txt$, $txt$Catat pola keringatmu selama dua minggu: kapan parah, apa pemicunya, apa yang membantu.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kapan Harus Waspada$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Segera konsultasikan ke dokter jika keringat berlebih muncul tiba-tiba di usia dewasa, terjadi terutama di malam hari disertai demam atau penurunan berat badan, atau hanya di satu sisi tubuh. Tanda-tanda itu bisa berkaitan dengan kondisi medis yang perlu diperiksa profesional. Artikel ini berisi informasi umum dan bukan pengganti nasihat medis; bila ragu, konsultasikan ke dokter atau fasilitas kesehatan terdekat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$Setelah dua minggu, keringat berkurang dan aktivitas sehari-hari lebih nyaman.$txt$, $txt$Pemicu utama sudah teridentifikasi dari catatan harianmu.$txt$, $txt$Jika tidak ada perbaikan, jadwalkan konsultasi ke dokter untuk pilihan terapi lanjutan.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Siapa Suku Tengger$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Suku Tengger adalah masyarakat yang mendiami kawasan pegunungan Bromo-Tengger-Semeru di Jawa Timur, meliputi Probolinggo, Pasuruan, Lumajang, dan Malang. Mereka dipercaya sebagai keturunan pelarian Kerajaan Majapahit yang menolak masuk Islam dan memilih bertahan di pegunungan. Hingga kini mereka memeluk Hindu Tengger, perpaduan Hindu dengan kepercayaan leluhur, dan hidup dari bertani di lahan vulkanik yang subur.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Yadnya Kasada: Upacara Agung$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Yadnya Kasada (sering disebut Kasodo) adalah upacara persembahan terbesar masyarakat Tengger, digelar setiap bulan Kasada penanggalan Jawa di kawah Gunung Bromo. Ribuan umat membawa sesaji berupa hasil bumi, ternak, hingga uang, lalu melemparkannya ke kawah sebagai persembahan kepada Sang Hyang Widhi. Upacara ini menarik puluhan ribu wisatawan setiap tahunnya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Legenda Roro Anteng dan Joko Seger$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Menurut legenda, pasangan Roro Anteng dan Joko Seger memohon keturunan dan dikaruniai 25 anak, dengan syarat anak bungsu bernama Kusuma harus dikorbankan ke kawah Bromo. Ketika janji itu ditagih, Kusuma terjun ke kawah sambil berpesan agar keturunannya tiap tahun memberi persembahan. Kisah inilah yang menjadi asal-usul Yadnya Kasada dan nama Tengger, dari teng (Roro Anteng) dan ger (Joko Seger).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Jalannya Upacara$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Rangkaian upacara dimulai dari Pura Luhur Poten di lautan pasir Bromo dengan doa bersama yang dipimpin para dukun pandita. Kemudian arak-arakan menuju puncak kawah, di mana sesaji dilemparkan ke dalam kawah yang mengepulkan asap belerang. Sebagian warga menuruni tebing kawah untuk menangkap sesaji yang dilempar, sebuah atraksi yang menegangkan sekaligus menjadi rezeki bagi mereka.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Makna dan Pelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Yadnya Kasada mengajarkan rasa syukur atas hasil bumi dan kesadaran bahwa manusia hidup berdampingan dengan alam yang dahsyat. Bagi masyarakat Tengger, gunung bukan sekadar latar pemandangan melainkan pusat spiritual. Di era pariwisata massal, tantangan terbesarnya adalah menjaga kesakralan upacara agar tidak sekadar menjadi tontonan, melestarikan warisan budaya yang sudah bertahan ratusan tahun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Kalsium: Mineral Terbanyak di Tubuh$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Kalsium adalah mineral yang paling banyak terdapat dalam tubuh manusia, sekitar 1 sampai 1,5 kilogram pada orang dewasa. Dalam tabel periodik ia bersimbol Ca dengan nomor atom 20, termasuk golongan logam alkali tanah. Sekitar 99 persen kalsium tubuh tersimpan di tulang dan gigi, sisanya beredar di darah dan jaringan untuk fungsi-fungsi penting lainnya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Peran Kalsium dalam Tubuh$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Selain membangun tulang dan gigi, kalsium membantu otot berkontraksi (termasuk jantung), menghantarkan sinyal saraf, dan berperan dalam pembekuan darah saat luka. Tubuh menjaga kadar kalsium darah dalam rentang sempit: jika asupan kurang, tubuh akan mengambilnya dari tulang, sehingga tulang perlahan melemah tanpa disadari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Sumber Kalsium Terbaik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Susu dan olahannya (yoghurt, keju) adalah sumber paling terkenal, tetapi ikan teri dan sarden yang dimakan dengan tulangnya, tahu, tempe, serta sayuran hijau seperti brokoli dan daun kelor juga kaya kalsium. Vitamin D dari sinar matahari pagi membantu tubuh menyerap kalsium, jadi keduanya adalah pasangan yang tidak terpisahkan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kekurangan Kalsium: Osteoporosis$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Kekurangan kalsium dalam jangka panjang menyebabkan tulang keropos (osteoporosis), sehingga mudah patah bahkan karena benturan ringan. Kelompok paling rentan adalah lansia dan wanita pascamenopause. Pencegahannya sederhana: cukupi asupan kalsium sejak muda, rutin berolahraga menahan beban seperti jalan kaki, dan berjemur pagi hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Fakta Menarik Kalsium di Alam$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Di alam, kalsium tidak pernah ditemukan murni melainkan sebagai senyawa: batu kapur dan marmer adalah kalsium karbonat, cangkang kerang dan telur pun tersusun dari senyawa yang sama. Stalaktit dan stalagmit di gua terbentuk dari endapan kalsium karbonat selama ribuan tahun. Dalam industri, kalsium dipakai untuk membuat semen, kapur tohor, hingga mengurangi kadar oksigen dalam produksi baja.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$txt$Menjelaskan pengertian pencemaran lingkungan dan polutan.$txt$, $txt$Mengidentifikasi jenis-jenis pencemaran beserta sumbernya.$txt$, $txt$Menganalisis dampak pencemaran bagi makhluk hidup.$txt$, $txt$Merumuskan upaya penanggulangan pencemaran di lingkungan sekitar.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Pencemaran Lingkungan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pencemaran lingkungan adalah masuknya zat, energi, atau komponen lain ke dalam lingkungan sehingga kualitasnya menurun sampai melewati baku mutu yang ditetapkan. Zat penyebabnya disebut polutan. Contohnya: asap kendaraan adalah polutan udara, limbah deterjen adalah polutan air, dan sampah plastik adalah polutan tanah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Jenis-jenis Pencemaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Pencemaran udara: gas buang kendaraan, asap pabrik, dan pembakaran sampah. Contoh dampaknya kabut asap dan hujan asam.$txt$, $txt$Pencemaran air: limbah industri, deterjen rumah tangga, dan pestisida yang dibuang ke sungai. Contoh dampaknya ikan mati massal.$txt$, $txt$Pencemaran tanah: sampah plastik, limbah B3, dan pupuk kimia berlebihan yang merusak kesuburan tanah.$txt$, $txt$Pencemaran suara: kebisingan dari lalu lintas, pabrik, dan konstruksi yang mengganggu pendengaran dan konsentrasi.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Dampak Pencemaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pencemaran berdampak pada tiga hal besar. Pertama, kesehatan manusia: ISPA akibat udara kotor, diare akibat air tercemar, hingga keracunan logam berat. Kedua, kerusakan ekosistem: terumbu karang memutih, hutan mati akibat hujan asam, dan rantai makanan terganggu. Ketiga, perubahan iklim: gas rumah kaca dari pembakaran mempercepat pemanasan global.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Upaya Penanggulangan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$Terapkan 3R (reduce, reuse, recycle) untuk menekan sampah sejak dari rumah.$txt$, $txt$Tanam pohon dan jaga daerah resapan air di lingkungan sekitar.$txt$, $txt$Industri wajib mengolah limbah lewat IPAL sebelum dibuang ke sungai.$txt$, $txt$Gunakan transportasi umum atau bersepeda untuk menekan emisi kendaraan.$txt$, $txt$Ikut kerja bakti membersihkan selokan dan sungai di lingkungan tempat tinggal.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$Soal 1: Jelaskan perbedaan polutan dan baku mutu lingkungan! Kunci: polutan adalah zat penyebab pencemaran, sedangkan baku mutu adalah batas kadar yang masih diperbolehkan.$txt$, $txt$Soal 2: Sebutkan dua contoh pencemaran air beserta sumbernya! Kunci: limbah deterjen dari rumah tangga dan limbah cair dari pabrik.$txt$, $txt$Soal 3: Tuliskan tiga upaya yang bisa kamu lakukan sebagai pelajar untuk mengurangi pencemaran! Kunci: memilah sampah, membawa botol minum sendiri, dan ikut menanam pohon.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$txt$Memahami pengertian denah dan perbedaannya dengan peta.$txt$, $txt$Menyebutkan delapan arah mata angin dengan benar.$txt$, $txt$Membaca denah sederhana seperti denah kelas dan denah rumah.$txt$, $txt$Menggambar denah sederhana lingkungan sekitar.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Denah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Denah adalah gambar yang menunjukkan letak suatu tempat, misalnya denah rumah, denah kelas, atau denah sekolah. Denah mirip peta, tetapi lebih sederhana dan biasanya hanya menggambarkan daerah kecil. Dengan denah, kita bisa menemukan letak ruangan atau benda tanpa harus datang langsung ke tempatnya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Arah Mata Angin$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Agar tidak tersesat saat membaca denah, kita perlu mengenal arah mata angin. Ada delapan arah mata angin: utara, timur laut, timur, tenggara, selatan, barat daya, barat, dan barat laut. Cara mudah mengingatnya: matahari terbit di timur dan terbenam di barat. Jika kita menghadap ke utara, maka kanan kita adalah timur dan kiri kita adalah barat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Cara Membaca Denah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Perhatikan dulu arah mata angin pada denah, biasanya ada tanda panah ke utara.$txt$, $txt$Cari keterangan gambar atau simbol, misalnya gambar meja, pintu, atau jendela.$txt$, $txt$Tentukan posisi benda dengan kalimat arah, contoh: meja guru di sebelah utara papan tulis.$txt$, $txt$Ukur jarak kira-kira dengan langkah kaki jika denah tidak memakai skala pasti.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh: Denah Ruang Kelas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Bayangkan denah kelasmu: papan tulis menempel di dinding sebelah utara, meja guru tepat di depan papan tulis, pintu kelas ada di dinding sebelah barat, dan jendela berjajar di dinding sebelah timur. Lemari buku diletakkan di sudut barat daya, sedangkan tempat sampah di sudut tenggara dekat pintu belakang. Dengan denah ini, teman yang belum pernah ke kelasmu pun bisa membayangkan letak setiap benda.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$Soal 1: Sebutkan delapan arah mata angin secara berurutan mulai dari utara! Kunci: utara, timur laut, timur, tenggara, selatan, barat daya, barat, barat laut.$txt$, $txt$Soal 2: Apa perbedaan denah dan peta? Kunci: denah lebih sederhana dan menggambarkan daerah kecil, sedangkan peta bisa menggambarkan daerah luas dengan skala pasti.$txt$, $txt$Soal 3: Gambarlah denah kamarmu sendiri, lalu tulis letak tempat tidur dan mejamu memakai arah mata angin! Kunci: jawaban beragam, dinilai dari ketepatan penggunaan arah mata angin.$txt$]));
